package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.Locale;
@Entity @Table(name="succession_readiness_criterion_finding",uniqueConstraints=@UniqueConstraint(name="uk_succ_readiness_criterion",columnNames={"agency_id","assessment_id","normalized_criterion_code"}))
public class SuccessionReadinessCriterionFinding extends RspAuditedEntity{
 public enum Outcome{MET,PARTIALLY_MET,NOT_MET,NEEDS_EVIDENCE}
 @Column(name="assessment_id",nullable=false,length=36)private String assessmentId;@Column(name="criterion_code",nullable=false,length=80)private String criterionCode;@Column(name="normalized_criterion_code",nullable=false,length=80)private String normalizedCriterionCode;@Column(name="criterion_label",nullable=false,length=200)private String criterionLabel;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(nullable=false,length=4000)private String rationale;@Column(name="source_reference",nullable=false,length=500)private String sourceReference;@Column(name="employee_visible",nullable=false)private boolean employeeVisible;@Column(name="display_order",nullable=false)private int displayOrder;
 protected SuccessionReadinessCriterionFinding(){}public SuccessionReadinessCriterionFinding(String a,String assessment,String code,String label,Outcome outcome,String rationale,String source,boolean visible,int order){super(a);assessmentId=requiredText(assessment,"assessmentId");criterionCode=requiredText(code,"criterionCode");normalizedCriterionCode=criterionCode.toUpperCase(Locale.ROOT);criterionLabel=requiredText(label,"criterionLabel");this.outcome=java.util.Objects.requireNonNull(outcome);this.rationale=requiredText(rationale,"rationale");sourceReference=requiredText(source,"sourceReference");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");employeeVisible=visible;displayOrder=order;}
 public String getAssessmentId(){return assessmentId;}public String getCriterionCode(){return criterionCode;}public String getCriterionLabel(){return criterionLabel;}public Outcome getOutcome(){return outcome;}public String getRationale(){return rationale;}public String getSourceReference(){return sourceReference;}public boolean isEmployeeVisible(){return employeeVisible;}public int getDisplayOrder(){return displayOrder;}
}
